/** Team → project tree with resource counts. Node ids: `team:<name>` and `project:<name>`. */
export function buildResourceTree(rows: readonly TreeResource[]): TreeNode[] {
  const teams = [...new Set(rows.map((r) => r.team))];
  return teams.map((team) => {
    const inTeam = rows.filter((r) => r.team === team);
    const projects = [...new Set(inTeam.map((r) => r.project))];
    return {
      id: `team:${team}`,
      label: team,
      icon: Building2,
      meta: String(inTeam.length),
      children: projects.map((p) => ({
        id: `project:${p}`,
        label: p,
        icon: FolderKanban,
        meta: String(inTeam.filter((r) => r.project === p).length),
      })),
    };
  });
}

/** Rows under a tree node id (`team:…`, `project:…`); `null` = all. */
export function rowsUnder(rows: readonly TreeResource[], nodeId: string | null): TreeResource[] {
  if (!nodeId) return [...rows];
  const [type, name] = nodeId.split(':');
  return rows.filter((r) => (type === 'team' ? r.team === name : r.project === name));
}

/** Groups rows by a field, in first-seen order. */
export function groupRows(
  rows: readonly TreeResource[],
  by: ResourceGroupBy,
): Array<{ key: string; label: string; rows: TreeResource[] }> {
  const keys = [...new Set(rows.map((r) => r[by]))];
  return keys.map((key) => ({
    key,
    label: by === 'kind' ? kindLabels[key as ResourceKind] : key,
    rows: rows.filter((r) => r[by] === key),
  }));
}

import { ChartLocaleProvider } from '@gntik-ai/charts';
import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import {
  SidebarLayout,
  useI18n,
  type BreadcrumbItem,
  type NavGroup,
  type SidebarLayoutProps,
  type UserMenuUser,
  type Workspace,
} from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends
    Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  const { locale } = useI18n();
  return (
    <ChartLocaleProvider locale={locale}>
      <SidebarLayout
        fullScreen
        storageKey={storageKey}
        sidebarLabel={sidebarLabel}
        collapseMode={collapseMode}
        sidebarHeader={({ collapsed }) => (
          <AppSidebarHeader
            collapsed={collapsed}
            workspaces={workspaces}
            currentWorkspaceId={currentWorkspaceId}
            onWorkspaceChange={onWorkspaceChange}
            onCreateWorkspace={onCreateWorkspace}
          />
        )}
        sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
        sidebarFooter={({ collapsed }) => (
          <AppSidebarFooter
            collapsed={collapsed}
            user={user}
            usage={usage}
            helpHref={helpHref}
            helpLabel={helpLabel}
            userMenuItems={userMenuItems}
            onSignOut={onSignOut}
          />
        )}
        topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
      >
        {children}
      </SidebarLayout>
    </ChartLocaleProvider>
  );
}
